<?php
require_once __DIR__ . '/../../includes/admin_auth.php'; require_admin();
$search = trim((string) ($_GET['q'] ?? ''));
$statement = $pdo->prepare('SELECT id, name, email, phone, subject, status, created_at FROM contact_messages WHERE CONCAT_WS(" ", name, email, phone, subject, message) LIKE :search ORDER BY created_at DESC');
$statement->execute(['search' => '%' . $search . '%']); $messages = $statement->fetchAll(); admin_header('Messages', 'messages/index.php');
?><div class="d-flex justify-content-between mb-3"><form class="d-flex gap-2" method="get"><input class="form-control" name="q" value="<?= e($search) ?>" placeholder="Search messages..."><button class="btn btn-outline-secondary" type="submit"><i class="bi bi-search"></i></button></form></div><div class="card table-card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Sender</th><th>Subject</th><th>Phone</th><th>Status</th><th>Date</th><th class="text-end">Actions</th></tr></thead><tbody><?php foreach ($messages as $message): ?><tr><td><strong><?= e($message['name']) ?></strong><small class="d-block text-secondary"><?= e($message['email']) ?></small></td><td><?= e($message['subject']) ?></td><td><?= e($message['phone'] ?: '—') ?></td><td><span class="badge text-bg-<?= strtolower($message['status']) === 'unread' ? 'danger' : 'secondary' ?>"><?= e(ucfirst($message['status'])) ?></span></td><td class="small text-secondary"><?= e(date('d M Y', strtotime($message['created_at']))) ?></td><td class="text-end"><a class="btn btn-sm btn-outline-primary" href="view.php?id=<?= e($message['id']) ?>">Read</a> <a class="btn btn-sm btn-outline-danger" href="delete.php?id=<?= e($message['id']) ?>">Delete</a></td></tr><?php endforeach; ?><?php if (!$messages): ?><tr><td colspan="6" class="text-center text-secondary py-5">No messages found.</td></tr><?php endif; ?></tbody></table></div></div><?php admin_footer(); ?>